#!/usr/bin/env python3

import sys

# Each leaf of the tests selects the operators of the 6 kinds used by the unique switch on the Iop
# (vr_instrumentOp_impl.h) : a kind is associated to a table generated by generateBackendInterOperator.py
bcKinds=["bcName","bcNameWithCC","bcNameWithCCUnfused","bcNameConv","bcNameConvWithCC","bcNameConvWithCCUnfused"]

def operators(fused, unfused, fusedConv, unfusedConv):
    return dict(zip(bcKinds, [fused, fused, unfused, fusedConv, fusedConv, unfusedConv]))

operatorsHard=(operators("vr_verrou_ROUNDING", "vr_unfused_verrou_ROUNDING", "vr_verrou_ROUNDING", "vr_unfused_verrou_ROUNDING"),
               operators("vr_verrou_ROUNDING", "vr_unfused_verrou_ROUNDING", "vr_conv_verrou_ROUNDING", "vr_unfused_conv_verrou_ROUNDING"))

operatorsSoft=(operators("vr_verrou_ROUNDING_soft", "vr_unfused_verrou_ROUNDING_soft", "vr_verrou_ROUNDING_soft", "vr_unfused_verrou_ROUNDING_soft"),
               operators("vr_verrou_ROUNDING_soft", "vr_unfused_verrou_ROUNDING_soft", "vr_conv_verrou_ROUNDING_soft", "vr_unfused_conv_verrou_ROUNDING_soft"))

operatorsSoftNearest=(operators("vr_verrou_ROUNDING", "vr_unfused_verrou_ROUNDING_soft", "vr_verrou_ROUNDING", "vr_unfused_verrou_ROUNDING_soft"),
                      operators("vr_verrou_ROUNDING", "vr_unfused_verrou_ROUNDING_soft", "vr_conv_verrou_ROUNDING_soft", "vr_unfused_conv_verrou_ROUNDING_soft"))


def leaf(ops):
    return "VR_SELECT_OPERATORS("+", ".join(ops[kind] for kind in bcKinds)+")\n"

def floatConvTest(pattern, transform):
    return "\tif(!vr.float_conv){\n%s\t}else{//vr.float_conv\n%s\t}//end float_conv\n"%(leaf(transform(pattern[0])), leaf(transform(pattern[1])))

def softTest(soft, hard):
    return "\tif(vr.instrument_soft_used || vr.instrument_soft_back_used){\n"+soft+"\t}else{//hard\n"+hard+"\t}//end vr.instrument_soft_used\n"


roundingList=[["NEAREST","NATIVE"],
              ["RANDOM"], ["NEARNESS"],
              ["RANDOM_DET"],["NEARNESS_DET"],
              ["RANDOM_COMDET"],["NEARNESS_COMDET"],
              ["RANDOM_SCOMDET"],["NEARNESS_SCOMDET"],
              ["SR_MONOTONIC"],["SR_SMONOTONIC"],
              ["UPWARD"],["DOWNWARD"],["ZERO"],
              ["AWAY_ZERO"],["FARTHEST"],["FLOAT"],
              ["PRANDOM"], ["PRANDOM_DET"], ["PRANDOM_COMDET"]
              ]

def replaceAll(ops, pattern, replace):
    return {kind:ops[kind].replace(pattern, replace) for kind in ops}

def replaceCC(ops, patternWithCC, replaceWithCC, patternWithoutCC, replaceWithoutCC):
    return {kind:(ops[kind].replace(patternWithCC, replaceWithCC) if "WithCC" in kind else ops[kind].replace(patternWithoutCC, replaceWithoutCC)) for kind in ops}

def replaceConv(ops, patternWithConv, replaceWithConv, patternWithoutConv, replaceWithoutConv):
    return {kind:(ops[kind].replace(patternWithConv, replaceWithConv) if "Conv" in kind else ops[kind].replace(patternWithoutConv, replaceWithoutConv)) for kind in ops}


def generateVerrouRounding(handler,roundingList):
    for rounding in roundingList:
        roundingMode=rounding[0]
        checkStr="if(vr.roundingMode==VR_"+roundingMode
        for checkRounding in rounding[1:]:
            checkStr+= " ||  vr.roundingMode==VR_" +checkRounding
        checkStr+="){\n"

        transformHard=lambda ops: replaceAll(ops, "ROUNDING", roundingMode)
        transformSoft=transformHard
        patternSoft=operatorsSoft
        if roundingMode=="NEAREST":
            patternSoft=operatorsSoftNearest
        if roundingMode=="FLOAT":
            transformHard=lambda ops: replaceConv(ops, "ROUNDING", roundingMode, "ROUNDING", "NEAREST")
            transformSoft=lambda ops: replaceConv(ops, "ROUNDING", roundingMode, "ROUNDING_soft", "NEAREST")

        strWrite=checkStr + softTest(floatConvTest(patternSoft, transformSoft), floatConvTest(operatorsHard, transformHard)) + "}\n"
        if roundingMode!="NEAREST":
            handler.write("#ifdef USE_VERROU_OPTIM\n")
        handler.write(strWrite)
        if roundingMode!="NEAREST":
            handler.write("#endif //USE_VERROU_OPTIM\n")

def checkPostbackend(backendName, postBackendList, postBackendName):
    res="vr.backend=="+backendName+" "
    for postBackend in postBackendList:
        if postBackend["postBackendName"]=="":
            continue
        res+= "&& "
        neg=""
        if postBackend["postBackendName"]!=postBackendName:
            neg="! "
        if postBackend["boolCheck"]!=None:
            res+= neg+postBackend["boolCheck"]
    return res




def generateVerrouGeneric(handler, backendEnum="vr_verrou", backendName="verrou", postBackendList=None):
    if postBackendList==None:
        transform=lambda ops: replaceAll(ops, "_ROUNDING", "")
        handler.write(softTest(floatConvTest(operatorsSoft, transform), floatConvTest(operatorsHard, transform)))
    else:
        for postBackend in postBackendList:
            def transform(ops):
                if postBackend["ccOnly"]:
                    res=replaceCC(ops, "_ROUNDING", postBackend["postBackendName"], "_ROUNDING", "")
                else:
                    res=replaceAll(ops, "_ROUNDING", postBackend["postBackendName"])
                return replaceAll(res, "verrou", backendName)

            res="if(" +checkPostbackend(backendEnum, postBackendList,postBackend["postBackendName"])+"){\n"
            if postBackend["convFloat"]:
                res+=softTest(floatConvTest(operatorsSoft, transform), floatConvTest(operatorsHard, transform))
            else:
                res+=softTest(leaf(transform(operatorsSoft[0])), leaf(transform(operatorsHard[0])))
            res+="}\n"
            handler.write(res)


if __name__=="__main__":

    fileName="vr_instrumentOp_impl_generated_verrou_specific.h"
    handler=open(fileName,"w")
    handler.write("// Generated by %s\n"%( str(sys.argv)[1:-1] ))
    handler.write("#ifndef DEBUG_PRINT_OP //the switch case with rounding mode during instrumentation is incompatible with DEBUG_PRINT_OP (to make it compatible python code generation need to be adapted)\n")
    generateVerrouRounding(handler,roundingList)
    handler.write("#endif\n")
    generateVerrouGeneric(handler)

    fileName="vr_instrumentOp_impl_generated_all_backends.h"
    handler=open(fileName,"w")
    handler.write("// Generated by %s\n"%( str(sys.argv)[1:-1] ))
    generateVerrouGeneric(handler, backendEnum="vr_verrou", backendName="verrou",
                          postBackendList=[{"postBackendName":"checkcancellation","boolCheck":"checkCancellation","convFloat":True ,"ccOnly":True },
                                           {"postBackendName":"check_float_max"  ,"boolCheck":"vr.checkFloatMax", "convFloat":False,"ccOnly":False}
                                           ])

    generateVerrouGeneric(handler, backendEnum="vr_checkdenorm", backendName="checkdenorm",
                          postBackendList= [{"postBackendName":"","boolCheck":None, "convFloat":True ,"ccOnly":False },
                                            {"postBackendName":"checkcancellation","boolCheck":"checkCancellation","convFloat":True ,"ccOnly":True }
                           ])
    handler.write("#ifdef USE_VERROU_VPREC\n")
    generateVerrouGeneric(handler, backendEnum="vr_vprec", backendName="vprec",
                          postBackendList= [ {"postBackendName":"","boolCheck":None, "convFloat":True ,"ccOnly":False },
                                             {"postBackendName":"checkcancellation","boolCheck":"checkCancellation","convFloat":True ,"ccOnly":True }
                                            ])
    handler.write("#endif //USE_VERROU_VPREC\n")

    handler.write("#ifdef USE_VERROU_QUADMATH\n")
    generateVerrouGeneric(handler, backendEnum="vr_mcaquad", backendName="mcaquad",
                          postBackendList= [ {"postBackendName":"","boolCheck":None, "convFloat":True ,"ccOnly":False },
                                             {"postBackendName":"checkcancellation","boolCheck":"checkCancellation","convFloat":True ,"ccOnly":True }
                           ])

    handler.write("#else //USE_VERROU_QUADMATH\n")
    handler.write("""
    if(vr.backend==vr_mcaquad){
            VG_(tool_panic) ( "Verrou compiled without quad support...  \\n");
    }
""")
    handler.write("#endif //USE_VERROU_QUADMATH\n")

